cat > bksearch.py <<'EOF_PY'
import bpy, json, urllib.request, urllib.parse, os
out = []
def p(*a): out.append(" ".join(str(x) for x in a))
key = ""
for name, ad in bpy.context.preferences.addons.items():
    if "blenderkit" in name.lower():
        key = getattr(ad.preferences, "api_key", "") or ""
p("key", bool(key))
H = {"User-Agent": "blenderkit/3.21.3 (Blender 5.2.3)", "accept": "application/json"}
AUTH = dict(H); AUTH["Authorization"] = "Bearer " + key
for name, ad in bpy.context.preferences.addons.items():
    if "blenderkit" in name.lower():
        pr = ad.preferences
        for a in dir(pr):
            if any(w in a.lower() for w in ("key", "token", "refresh", "expire")):
                v = getattr(pr, a, None)
                p("pref", a, type(v).__name__, len(v) if isinstance(v, str) else v)
try:
    u = "https://www.blenderkit.com/api/v1/downloads/f6abe4eb-c0c3-4c83-80e7-ebadd862d177/?scene_uuid=1b4e28ba-2fa1-11d2-883f-0016d3cca427"
    r = urllib.request.urlopen(urllib.request.Request(u, headers=AUTH), timeout=30)
    p("download test OK", str(json.loads(r.read().decode()).get("filePath", ""))[:40])
except Exception as e: p("download test", e)
Q = ["espresso machine", "coffee machine", "sci-fi espresso machine", "portafilter", "espresso cup", "coffee beans", "coffee grinder", "tamper coffee", "pressure gauge", "water pump", "heating element", "milk jug", "barista counter", "kitchen counter modern", "coffee cup saucer", "steam wand"]
os.makedirs("th", exist_ok=True)
n = 0
for q in Q:
    try:
        url = "https://www.blenderkit.com/api/v1/search/?" + urllib.parse.urlencode({"query": q + " asset_type:model order:-score", "page_size": 10})
        if q == "concrete floor":
            url = "https://www.blenderkit.com/api/v1/search/?" + urllib.parse.urlencode({"query": q + " asset_type:material order:-score", "page_size": 6})
        d = json.load(urllib.request.urlopen(urllib.request.Request(url, headers=H), timeout=40))
        p("## search", repr(q), "count", d.get("count"))
        for r in d.get("results", [])[:10]:
            bl = [f.get("downloadUrl") for f in r.get("files", []) if f.get("fileType") == "blend"]
            dims = [r.get("dimensionX"), r.get("dimensionY"), r.get("dimensionZ")]
            ab = r.get("assetBaseId"); th = r.get("thumbnailMiddleUrl") or r.get("thumbnailSmallUrl")
            n += 1
            p("[%03d]" % n, r.get("name"), "| base", ab, "| dl", bl[0] if bl else None, "| free", r.get("isFree"), "| can", r.get("canDownload"), "| dims", dims, "| score", r.get("score"), "| polys", (r.get("dictParameters") or {}).get("faceCount"))
            if th:
                try:
                    data = urllib.request.urlopen(urllib.request.Request(th, headers={"User-Agent": H["User-Agent"]}), timeout=30).read()
                    open("th/%03d.jpg" % n, "wb").write(data)
                except Exception as e: p("  thumb err", e)
    except Exception as e:
        p("search error", q, e)
open("bksearch.txt", "w").write("\n".join(out) + "\n")
EOF_PY
/Applications/Blender.app/Contents/MacOS/Blender -b -P bksearch.py > bl.log 2>&1; test -s bksearch.txt || (tail -20 bl.log > bksearch.txt); head -3 bksearch.txt; cd "$AGENT_HOME/pilot_test/film" && for f in "$JOB_DIR"/th/*.jpg; do npx remotion ffmpeg -y -v error -i "$f" -vf 'scale=200:200:force_original_aspect_ratio=decrease,pad=200:200:(ow-iw)/2:(oh-ih)/2:color=white' "${f%.jpg}_s.jpg" || true; done; cd "$JOB_DIR"; a="bksearch.txt esp/bksearch.txt"; for f in th/*_s.jpg; do a="$a $f esp/th/$(basename $f)"; done; "$AGENT_HOME/node/bin/node" "$AGENT_HOME/repo/tools/push_preview.mjs" $a | tail -2
